152	fn train_caption(stripped: &str) -> &'static str {
153	    // Parse the iteration count out of `train N {...}`. Small
154	    // chunks (<=10) get a chunk-shaped message ("the page will
155	    // un-freeze between chunks"); larger blocks keep the
156	    // long-duration warning.
157	    let after_train = stripped["train ".len()..].trim_start();
158	    let count: usize = after_train
159	        .split(|c: char| !c.is_ascii_digit())
160	        .next()
161	        .unwrap_or("")
162	        .parse()
163	        .unwrap_or(0);
164	    if count > 0 && count <= 10 {
165	        "training chunk... (a few seconds; the page un-freezes between chunks)"
166	    } else {
167	        "training... (this can take 30-90 seconds; the page is unresponsive while WASM runs)"
168	    }
169	}
