286	fn schedule_demo_line(
287	    session: Rc<RefCell<WasmSession>>,
288	    history: UseStateHandle<Vec<HistoryEntry>>,
289	    mut entries: Vec<HistoryEntry>,
290	    demo: &'static crate::demos::Demo,
291	    idx: usize,
292	) {
293	    let lines = demo.lines;
294	    if idx >= lines.len() {
295	        // Last line ran -- append the takeaway narration panel
296	        // and paint the final history state.
297	        entries.push(HistoryEntry {
298	            input: "What just happened".to_string(),
299	            output: demo.takeaway.to_string(),
300	            is_error: false,
301	            kind: EntryKind::Narration,
302	        });
303	        history.set(entries);
304	        return;
305	    }
306	    push_progress_notes(&mut entries, demo.name, idx);
307	    let line = lines[idx];
308	    push_running_marker(&mut entries, line);
309	    history.set(entries.clone());
310	    let session_next = Rc::clone(&session);
311	    let history_next = history.clone();
312	    gloo::timers::callback::Timeout::new(0, move || {
313	        let result = session.borrow().eval(line);
314	        replace_running_with_result(&mut entries, line, result);
315	        history.set(entries.clone());
316	        schedule_demo_line(session_next, history_next, entries, demo, idx + 1);
317	    })
318	    .forget();
319	}
