const KEY_SPLASH_DISMISSED: &str = "mlpl_splash_dismissed";
const KEY_LAST_VERSION: &str = "mlpl_last_seen_version";

pub fn should_show_splash(dismissed: bool) -> bool {
    !dismissed
}

pub fn should_show_whats_new(last_seen: Option<&str>, current: &str) -> bool {
    match last_seen {
        None => false,
        Some(v) => v != current,
    }
}

pub fn read_splash_dismissed() -> bool {
    local_storage_get(KEY_SPLASH_DISMISSED).is_some()
}

pub fn write_splash_dismissed() {
    local_storage_set(KEY_SPLASH_DISMISSED, "1");
}

pub fn read_last_seen_version() -> Option<String> {
    local_storage_get(KEY_LAST_VERSION)
}

pub fn write_last_seen_version(version: &str) {
    local_storage_set(KEY_LAST_VERSION, version);
}

fn local_storage_get(key: &str) -> Option<String> {
    web_sys::window()?
        .local_storage()
        .ok()
        .flatten()?
        .get_item(key)
        .ok()
        .flatten()
}

fn local_storage_set(key: &str, value: &str) {
    if let Some(storage) = web_sys::window()
        .and_then(|w| w.local_storage().ok().flatten())
    {
        let _ = storage.set_item(key, value);
    }
}

#[cfg(test)]
mod tests {
    use super::{should_show_splash, should_show_whats_new};

    #[test]
    fn splash_shows_when_not_dismissed() {
        assert!(should_show_splash(false));
        assert!(!should_show_splash(true));
    }

    #[test]
    fn whats_new_shows_on_version_change() {
        assert!(should_show_whats_new(Some("0.19.0"), "0.20.0"));
        assert!(!should_show_whats_new(Some("0.20.0"), "0.20.0"));
    }

    #[test]
    fn whats_new_skips_first_visit() {
        assert!(!should_show_whats_new(None, "0.20.0"));
    }
}

