                "list_get: index {i} out of bounds (list has {} items)",
                items.len()
            );
            (false, msg)
        },
        |s| (true, s.clone()),
    );
    Ok(Value::Result {
        ok,
        payload: Box::new(Value::Str(s)),
    })
}

