#[derive(Clone, Copy, Debug, PartialEq)]
pub enum HeaderMode {
    Repl,
    Tutorial,
    Paths,
}

#[derive(Properties, PartialEq)]
pub struct HeaderProps {
    pub on_help: Callback<MouseEvent>,
