        .and_then(|w| w.document())
        .and_then(|d| d.query_selector(&sel).ok()?)
        .map(|el| {
            let r = el
                .unchecked_into::<web_sys::Element>()
                .get_bounding_client_rect();
            Rect {
                top: r.top(),
                left: r.left(),
                width: r.width(),
                height: r.height(),
            }
