14	        .parse()
15	        .unwrap_or(0);
16	    let commit_count = (raw_count + 1).to_string();
17	    let timestamp = run_cmd("date", &["-u", "+%Y-%m-%dT%H:%M:%SZ"]);
18	    println!("cargo:rustc-env=BUILD_HOST={host}");
19	    println!("cargo:rustc-env=BUILD_SHA={sha}");
20	    println!("cargo:rustc-env=BUILD_COMMIT_COUNT={commit_count}");
21	    println!("cargo:rustc-env=BUILD_TIMESTAMP={timestamp}");
22	    println!("cargo:rerun-if-changed=.git/HEAD");
23	}

