    pub on_select_paths: Callback<MouseEvent>,
    pub mode: HeaderMode,
}

#[function_component(Header)]
pub fn header(props: &HeaderProps) -> Html {
    let cls = |m: HeaderMode| {
        if props.mode == m { "tab active" } else { "tab" }
