1	//! Saga 33 step 006: main-pane composer extracted from
2	//! `main.rs::render_main`. The original 42-LOC body inlined
3	//! three panes + a shell-layout match; now each pane is its
4	//! own helper and `render_main` is a 7-line composer.
5	
6	use yew::prelude::*;
7	
8	use crate::components::{InputRow, Welcome};
9	use crate::entry_render::render_entry;
10	use crate::mode_callbacks::ModeCallbacks;
11	use crate::paths_view;
12	use crate::render_tutorial::render_tutorial;
13	use mlpl_web_eval::state::HistoryEntry;
14	
15	pub struct MainArgs<'a> {
16	    pub tutorial_active: bool,
17	    pub paths_active: bool,
18	    pub cur_lesson: Option<usize>,
19	    pub lesson_idx: UseStateHandle<Option<usize>>,
20	    pub initial_view: crate::components::TutorialView,
21	    pub cur_path: Option<(Option<usize>, usize)>,
22	    pub cb: &'a ModeCallbacks,
23	    pub history: &'a UseStateHandle<Vec<HistoryEntry>>,
24	    pub input_value: &'a UseStateHandle<String>,
25	    pub on_input: Callback<InputEvent>,
26	    pub on_keydown: Callback<web_sys::KeyboardEvent>,
27	    pub on_run_example: Callback<String>,
28	    pub on_run_batch: Callback<Vec<String>>,
29	    pub completion_candidates: Vec<String>,
30	    pub on_pick_completion: Callback<String>,
31	    pub completion_selected: usize,
32	    pub show_3d: bool,
33	}
34	
35	pub fn render_main(a: MainArgs) -> Html {
36	    let tutorial_pane = render_tutorial(
37	        a.cur_lesson,
38	        a.lesson_idx,
39	        a.initial_view,
40	        a.on_run_example,
41	        a.on_run_batch,
42	        a.cur_path.is_some(),
43	    );
44	    let paths_pane = render_paths_pane(a.cur_path, a.cb);
45	    let repl_pane = render_repl_pane(ReplPaneArgs {
46	        history: a.history,
47	        input_value: a.input_value,
48	        on_input: a.on_input,
49	        on_keydown: a.on_keydown,
50	        tutorial_active: a.tutorial_active,
51	        paths_active: a.paths_active,
52	        completion_candidates: a.completion_candidates,
53	        on_pick_completion: a.on_pick_completion,
54	        completion_selected: a.completion_selected,
55	    });
56	    render_main_shell(
57	        a.tutorial_active,
58	        a.show_3d,
59	        tutorial_pane,
60	        paths_pane,
61	        repl_pane,
62	    )
63	}
64	
65	/// PathsView render: thin wrapper so the parent doesn't need to
66	/// know about `paths_view::PathsView`'s prop shape.
67	fn render_paths_pane(cur_path: Option<(Option<usize>, usize)>, cb: &ModeCallbacks) -> Html {
68	    html! {
69	        <paths_view::PathsView
70	            state={cur_path}
71	            on_change={cb.path_change.clone()}
72	            on_open_lesson={cb.path_open_lesson.clone()}
73	            on_run_demo={cb.path_run_demo.clone()}
74	        />
75	    }
76	}
77	
78	struct ReplPaneArgs<'a> {
79	    history: &'a UseStateHandle<Vec<HistoryEntry>>,
80	    input_value: &'a UseStateHandle<String>,
81	    on_input: Callback<InputEvent>,
82	    on_keydown: Callback<web_sys::KeyboardEvent>,
83	    tutorial_active: bool,
84	    paths_active: bool,
85	    completion_candidates: Vec<String>,
86	    on_pick_completion: Callback<String>,
87	    completion_selected: usize,
88	}
89	
90	fn render_repl_pane(a: ReplPaneArgs) -> Html {
91	    let welcome = if a.tutorial_active || a.paths_active {
92	        html! {}
93	    } else {
94	        html! { <Welcome /> }
95	    };
96	    let value = (**a.input_value).clone();
97	    html! {
98	        <>
99	            <div id="output" class="output">
100	                { welcome }
101	                { for a.history.iter().map(render_entry) }
102	            </div>
103	            <InputRow
104	                {value}
105	                on_input={a.on_input}
106	                on_keydown={a.on_keydown}
107	                in_tutorial={a.tutorial_active}
108	                completion_candidates={a.completion_candidates}
109	                on_pick_completion={a.on_pick_completion}
110	                completion_selected={a.completion_selected}
111	            />
112	        </>
113	    }
114	}
115	
116	/// Layout shell: when the tutorial is active, render a 2-pane
117	/// split (tutorial + repl); otherwise stack the panes in a
118	/// single `<main>` container.
119	fn render_main_shell(
120	    tutorial_active: bool,
121	    show_3d: bool,
122	    tutorial_pane: Html,
123	    paths_pane: Html,
124	    repl_pane: Html,
125	) -> Html {
126	    let stage = if show_3d {
127	        html! { <section class="stage3d-pane"><canvas id="stage3d" /></section> }
128	    } else {
129	        html! {}
130	    };
131	    if tutorial_active {
132	        html! {
133	            <main class="tutorial-split">
134	                <section class="tutorial-pane">{ tutorial_pane }</section>
135	                <section class="repl-pane">{ repl_pane }{ stage }</section>
136	            </main>
137	        }
138	    } else {
139	        let cls = if show_3d { "viz3d-split" } else { "" };
140	        html! {
141	            <main class={cls}>
142	                { tutorial_pane }
143	                { paths_pane }
144	                { repl_pane }
145	                { stage }
146	            </main>
147	        }
148	    }
149	}
